// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const tutorialPath = path.resolve(__dirname, '../../site/static/lmdb-adjacency-tutorial/index.html');
const html = fs.readFileSync(tutorialPath, 'utf8');

function extractScript(id) {
    const match = html.match(new RegExp(`<script id="${id}">([\\s\\S]*?)</script>`));
    assert.ok(match, `missing inline script ${id}`);
    return match[1];
}

function loadCore() {
    const context = { atob };
    context.globalThis = context;
    vm.runInNewContext(extractScript('adjacency-core'), context, { filename: 'adjacency-core.js' });
    return context.Rdf4jAdjacencyTutorialCore;
}

function fixtures(core) {
    const match = html.match(/<script id="csf-page-fixtures" type="text\/plain">([\s\S]*?)<\/script>/);
    assert.ok(match, 'missing page fixture block');
    return core.parseFixtures(match[1]);
}

function numbers(values) {
    return Array.from(values, Number);
}

const core = loadCore();

test('raw ID tags and RDF role rules are exact', () => {
    assert.equal(core.makeId(core.TYPE.URI, 1), 130n);
    assert.equal(core.makeId(core.TYPE.LITERAL, 8), 1028n);
    assert.equal(core.makeId(core.TYPE.BNODE, 10), 1286n);
    assert.equal(core.makeId(core.TYPE.TRIPLE, 12), 1544n);
    assert.equal(core.rawType(1544n), core.TYPE.TRIPLE);
    assert.equal(core.rawPayload(1544n), 12n);

    assert.equal(core.isValidForRole(core.TERMS.alice, 'subject'), true);
    assert.equal(core.isValidForRole(core.TERMS.team, 'subject'), true);
    assert.equal(core.isValidForRole(core.TERMS.aliceKnowsBob, 'subject'), true);
    assert.equal(core.isValidForRole(core.TERMS.bobLabel, 'subject'), false);
    assert.equal(core.isValidForRole(core.TERMS.bobLabel, 'object'), true);
    assert.equal(core.isValidForRole(core.DEFAULT_CONTEXT, 'context'), true);
    assert.equal(core.isValidForRole(core.TERMS.team, 'context'), true);
    assert.equal(core.isValidForRole(core.TERMS.aliceKnowsBob, 'context'), false);
    assert.equal(core.isValidForRole(core.TERMS.knows, 'predicate'), true);
    assert.equal(core.isValidForRole(core.TERMS.bobLabel, 'predicate'), false);
});

test('all planes and both orientations route to the expected rows', () => {
    assert.deepEqual(Array.from(core.PARTITIONS.keys()), ['0:0', '0:1', '0:2', '0:3', '1:0', '1:1']);

    const outgoing = core.traceStatement(0, 'outgoing');
    assert.equal(outgoing.key, '0:0');
    assert.equal(outgoing.plane, 0);
    assert.equal(outgoing.rowId, 130n);
    assert.equal(outgoing.neighborId, 386n);

    const incoming = core.traceStatement(0, 'incoming');
    assert.equal(incoming.key, '0:1');
    assert.equal(incoming.plane, 1);
    assert.equal(incoming.rowId, 386n);
    assert.equal(incoming.neighborId, 130n);

    assert.equal(core.traceStatement(7, 'outgoing').plane, 2);
    assert.equal(core.traceStatement(7, 'incoming').plane, 3);
    assert.equal(core.traceStatement(4, 'incoming').rowId, 1028n, 'literal object is a legal incoming row');
});

test('nested CSR arrays preserve rows, distinct neighbors, and context memberships', () => {
    const csr = core.nestedCsr(core.PARTITIONS.get('0:0'));
    assert.deepEqual(numbers(csr.rowIds), [130, 386, 1286, 1544]);
    assert.deepEqual(numbers(csr.rowPtr), [0, 2, 3, 4, 5]);
    assert.deepEqual(numbers(csr.colIdx), [386, 642, 130, 130, 130]);
    assert.deepEqual(numbers(csr.contextPtr), [0, 2, 3, 4, 5, 6]);
    assert.deepEqual(numbers(csr.contextIdx), [514, 770, 514, 0, 1414, 1666]);

    const sharedFiber = core.traceStatement(2, 'outgoing');
    assert.deepEqual(Array.from(sharedFiber.rowSpan), [0, 2]);
    assert.deepEqual(Array.from(sharedFiber.contextSpan), [0, 2]);
    assert.equal(sharedFiber.rowIndex, 0);
    assert.equal(sharedFiber.fiberIndex, 0);
    assert.equal(sharedFiber.contextIndex, 1);
});

test('compact columns factor first values and omit page-wide invariants', () => {
    const compact = core.compactColumns(core.PARTITIONS.get('0:0'));
    assert.equal(compact.flags, 0);
    assert.deepEqual(numbers(compact.rowFiberStarts), [0, 2, 3, 4]);
    assert.deepEqual(numbers(compact.rowQuadCounts), [3, 1, 1, 1]);
    assert.deepEqual(numbers(compact.firstNeighbors), [386, 130, 130, 130]);
    assert.deepEqual(numbers(compact.neighborTails), [256]);
    assert.deepEqual(numbers(compact.contextCounts), [2, 1, 1, 1, 1]);
    assert.deepEqual(numbers(compact.firstContexts), [514, 514, 0, 1414, 1666]);
    assert.deepEqual(numbers(compact.contextTails), [256]);

    const singleton = core.compactColumns(core.PARTITIONS.get('0:2'));
    assert.equal(singleton.flags, 30);
    assert.equal(singleton.rowFiberStarts, null);
    assert.equal(singleton.rowQuadCounts, null);
    assert.equal(singleton.neighborTails, null);
    assert.equal(singleton.contextCounts, null);
    assert.equal(singleton.firstContexts, null);
    assert.equal(singleton.contextTails, null);
    assert.equal(singleton.commonContext, 514n);
});

test('embedded v3 pages decode through vector directories and packed lanes', () => {
    const pageFixtures = fixtures(core);
    assert.deepEqual(Array.from(pageFixtures.keys()), ['0:0', '0:1', '0:2', '0:3', '1:0', '1:1']);
    const expectedSizes = new Map([
        ['0:0', [432, 512]],
        ['0:1', [424, 512]],
        ['0:2', [224, 256]],
        ['0:3', [224, 256]],
        ['1:0', [224, 256]],
        ['1:1', [224, 256]]
    ]);

    for (const [key, bytes] of pageFixtures) {
        const page = core.decodePage(bytes);
        assert.equal(page.header.version, 3);
        assert.equal(page.header.formatHash, 0x72b9c4e1);
        assert.deepEqual([page.header.usedBytes, page.header.capacity], expectedSizes.get(key));
        for (const section of page.sections.filter((candidate) => candidate.vector)) {
            assert.equal(section.offset % 8, 0);
            assert.equal(section.vector.directory.at(-1), section.length);
            assert.equal(section.vector.values.length, section.vector.count);
            assert.ok(section.vector.blocks.every((block) => block.count <= 256));
        }
    }

    const page = core.decodePage(pageFixtures.get('0:0'));
    const rowIds = page.sections.find((section) => section.name === 'rowIds');
    const firstNeighbors = page.sections.find((section) => section.name === 'firstNeighbors');
    assert.deepEqual(numbers(rowIds.vector.values), [130, 386, 1286, 1544]);
    assert.equal(rowIds.vector.blocks[0].modeName, 'FOR raw', 'mixed row term types retain raw IDs');
    assert.deepEqual(numbers(firstNeighbors.vector.values), [386, 130, 130, 130]);
    assert.equal(firstNeighbors.vector.blocks[0].modeName, 'FOR typed payload', 'homogeneous URI block strips type tags');

    const trace = core.traceStatement(2, 'outgoing');
    const physical = core.defaultPhysicalLane(page, trace);
    assert.deepEqual({ sectionName: physical.sectionName, lane: physical.lane }, { sectionName: 'contextTails', lane: 0 });
    assert.equal(core.vectorLane(page, physical.sectionName, physical.lane).lane.value, 256n);
});

test('small delta runs encode complete sorted rows with neighbor deltas and context ordinals', () => {
    const run = core.encodeSmallRun([
        { neighbor: core.TERMS.bob.rawId, rawContext: core.TERMS.work.rawId, contextOrdinal: 2n },
        { neighbor: core.TERMS.carol.rawId, rawContext: core.TERMS.friends.rawId, contextOrdinal: 1n },
        { neighbor: core.TERMS.carol.rawId, rawContext: core.TERMS.work.rawId, contextOrdinal: 2n }
    ]);

    assert.equal(run.tag, 0x04, 'SMALL_VARINT with context ordinals and general neighbor IDs');
    assert.equal(run.count, 3);
    assert.equal(run.neighborByteLength, 5);
    assert.equal(run.contextByteLength, 3);
    assert.equal(run.usedBytes, 16);
    assert.equal(run.alignedBytes, 16);
    assert.deepEqual(numbers(run.bytes), [
        0x04, 0x03, 0x05, 0x00, 0x03, 0x00, 0x00, 0x00,
        0xf1, 0x92, 0xf1, 0x10, 0x00,
        0x02, 0x01, 0x02
    ]);

    assert.throws(() => core.encodeSmallRun([
        { neighbor: 642n, rawContext: 770n, contextOrdinal: 2n },
        { neighbor: 386n, rawContext: 514n, contextOrdinal: 1n }
    ]), /strictly unsigned/);
});
